from pathlib import Path
root=Path('mentat/tests')
p=root/'test_insights_browser.cjs';s=p.read_text(encoding='utf-8')
s=s.replace("assert.equal(widths,3,'Wide console follows the three-column design');","assert.equal(widths,2,'Supporting analyses use two columns below the dominant trend chart');")
s=s.replace("nodes=>nodes.map(node=>node.getBoundingClientRect().top)","nodes=>nodes.slice(1).map(node=>node.getBoundingClientRect().top)")
s=s.replace("Desktop core headings align","Supporting desktop headings align").replace("Desktop source footers align","Supporting source footers align")
p.write_text(s,encoding='utf-8')
p=root/'test_evidence_panes_browser.cjs';s=p.read_text(encoding='utf-8')
s=s.replace("() => [...document.querySelectorAll('#evidence-pac option')].map(node => node.value).join('|'));","() => document.querySelector('#evidence-status').textContent);")
s=s.replace("return now.length > 0 && now !== previous;","return now.length > 0 && document.querySelector('#evidence-status').textContent !== previous && !document.querySelector('#evidence-add').disabled;")
s=s.replace('Wait for the list to actually CHANGE.','Wait for the source status to change; both sources may contain the same PAC.')
p.write_text(s,encoding='utf-8')
p=root/'test_evidence_map_browser.cjs';s=p.read_text(encoding='utf-8')
s=s.replace("const ranked = document.querySelector('#evidence-map .map-ranked');","const ranked = document.querySelector('#evidence-map .map-detail');")
p.write_text(s,encoding='utf-8')
p=root/'test_evidence_map_interaction_browser.cjs';s=p.read_text(encoding='utf-8')
import re
s=re.sub(r"await page.click\('(#[^']+ )?\.map-layer\[data-map-layer=\"([^\"]+)\"\]'\);",r"await page.selectOption('#evidence-map-layer-select','\2');",s)
s=s.replace('await page.click(`#evidence-map .map-layer[data-map-layer="${key}"]`);',"await page.selectOption('#evidence-map-layer-select',key);")
s=s.replace("await page.click('#evidence-map-reset');","if(!await page.locator('.map-navigation-options').evaluate(el=>el.open))await page.locator('.map-navigation-options > summary').click();\n    await page.click('#evidence-map-reset');")
s=s.replace("await page.fill('#evidence-map-search', 'TX-19');","if(!await page.locator('.map-navigation-options').evaluate(el=>el.open))await page.locator('.map-navigation-options > summary').click();\n    await page.fill('#evidence-map-search', 'TX-19');")
s=s.replace(".map-ranked h2", ".map-detail h2")
p.write_text(s,encoding='utf-8')
